def valid_image(raw):
    """Accept the PNG fixture format; production image decoding is outside this demo."""
    return len(raw) >= 24 and raw.startswith(b"\x89PNG\r\n\x1a\n") and raw[12:16] == b"IHDR"

review-policy.snippet:
def approval_policy(actor, current_version, reviewed_version):
    """Only a reviewer who opened the current image may publish it."""
    if actor != "reviewer":
        return "forbidden"
    if reviewed_version != current_version:
        return "stale_review"
    return "allowed"

